#include <memory>
#include <set>
#include <vector>

struct Monster
{
    int index;
    int health{ 50 };
};

std::vector<std::unique_ptr<Monster>> spawnWave(int count, const std::set<int>& blocked)
{
    std::vector<std::unique_ptr<Monster>> placed;
    for (int i{ 0 }; i < count; ++i)
    {
        Monster* m{ new Monster{ i } };
        if (blocked.count(i)) continue;          // cannot be placed
        placed.push_back(std::unique_ptr<Monster>(m));
    }
    return placed;
}

solution.solution.cpp:
#include <memory>
#include <set>
#include <vector>

struct Monster
{
    int index;
    int health{ 50 };
};

std::vector<std::unique_ptr<Monster>> spawnWave(int count, const std::set<int>& blocked)
{
    std::vector<std::unique_ptr<Monster>> placed;
    for (int i{ 0 }; i < count; ++i)
    {
        auto m{ std::make_unique<Monster>(Monster{ i }) };   // owned from the start
        if (blocked.count(i)) continue;                      // freed automatically here
        placed.push_back(std::move(m));
    }
    return placed;
}

unitTests:
TEST("the right monsters are placed")
{
    const auto wave{ spawnWave(5, { 1, 3 }) };
    CHECK_EQ(wave.size(), std::size_t{ 3 });
    CHECK_EQ(wave[0]->index, 0);
    CHECK_EQ(wave[1]->index, 2);
    CHECK_EQ(wave[2]->index, 4);
}
TEST("nothing blocked")
{
    CHECK_EQ(spawnWave(4, {}).size(), std::size_t{ 4 });
}
TEST("no leak when monsters are blocked")
{
    CHECK_NO_LEAK({ auto wave{ spawnWave(10, { 0, 2, 4, 6, 8 }) }; });
}
TEST("no leak when everything is blocked")
{
    CHECK_NO_LEAK({ auto wave{ spawnWave(3, { 0, 1, 2 }) }; });
}

